/**
 * Hands a project to a new lead, or clears the lead with `leadId: null`. It
 * is its own operation so the `project:change_lead` permission, not a general
 * project edit, decides who may do it. A new lead must be an active member of
 * the organization who could edit the project themselves.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const member = await memberRepo.findMember(input.orgId, input.leadId);
    if (member === null || member.status !== "active") {
      throw new NotFoundError("Member", input.leadId);
    }

    // Judged as the new lead, with their own role: staff status is not
    // carried over, so a non-staff lead is checked by role alone.
    assertCan(
      { userId: input.leadId, orgId: input.orgId, role: member.role },
      "project:update",
      projectResource(project),
    );
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}

